import numpy as np
import heapq

def huffman_encoding(symbols, probabilities):
    heap = []
    for i, (sym, prob) in enumerate(zip(symbols, probabilities)):
        heapq.heappush(heap, (prob, i, [sym, '']))

    counter = len(symbols)
    while len(heap) > 1:
        prob1, _, node1 = heapq.heappop(heap)
        prob2, _, node2 = heapq.heappop(heap)

        merged = []
        if isinstance(node1[0], list):
            for item in node1:
                merged.append([item[0], '0' + item[1]])
        else:
            merged.append([node1[0], '0' + node1[1]])

        if isinstance(node2[0], list):
            for item in node2:
                merged.append([item[0], '1' + item[1]])
        else:
            merged.append([node2[0], '1' + node2[1]])

        heapq.heappush(heap, (prob1 + prob2, counter, merged))
        counter += 1

    _, _, final_node = heap[0]
    codes = {}
    if isinstance(final_node[0], list):
        for item in final_node:
            codes[item[0]] = item[1]
    else:
        codes[final_node[0]] = final_node[1]

    return codes

def average_code_length(codes, probabilities, symbols):
    avg_length = sum(prob * len(codes[sym]) for sym, prob in zip(symbols, probabilities))
    return avg_length

def encoding_efficiency(codes, probabilities, symbols):
    p = np.array(probabilities)
    entropy = -np.sum(p * np.log2(p))
    avg_len = average_code_length(codes, probabilities, symbols)
    efficiency = entropy / avg_len
    return efficiency

symbols = ['A', 'B', 'C', 'D', 'E']
probs = [0.35, 0.25, 0.20, 0.15, 0.05]
codes = huffman_encoding(symbols, probs)
print(f"Huffman codes: {codes}")
print(f"Average length: {average_code_length(codes, probs, symbols):.4f}")
